// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';


export type HourglassAnimationProps = Record<string, any>;

const HourglassAnimation: React.FC<HourglassAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  hourglassColor = "#e5e5e5",
  sandColor = "#d4d4d4",
  entranceDurationFrames = 30,
  durationInSeconds = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background Logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive Scaling
  const size = Math.min(width, height) * 0.7;
  const svgWidth = size * (2 / 3);
  const svgHeight = size;

  // --- Animation Timings ---
  // Entrance
  const entranceScale = spring({
    fps,
    frame,
    config: { damping: 14, mass: 0.8 },
  });
  const entranceOpacity = interpolate(
    frame,
    [0, entranceDurationFrames / 2],
    [0, 1],
    { extrapolateRight: "clamp" }
  );

  // Sand Falling Phases
  const fallStart = entranceDurationFrames + 5;
  const totalFrames = durationInSeconds * fps;
  const stillDuration = 45; // Frames at the end where everything is completely still
  const fallEnd = totalFrames - stillDuration;

  const streamHitsBottom = fallStart + 15;
  const topSandEmpty = fallEnd - 15;

  // --- Interpolations ---
  // Top sand moves down
  const topSandY = interpolate(frame, [fallStart, topSandEmpty], [0, 140], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Bottom sand moves up
  const bottomSandY = interpolate(
    frame,
    [streamHitsBottom, fallEnd],
    [300, 168],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Stream of sand growing down, then shrinking down
  const streamTopY = interpolate(frame, [topSandEmpty, fallEnd], [150, 280], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const streamBottomY = interpolate(
    frame,
    [fallStart, streamHitsBottom],
    [150, 280],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Determine if stream should be visible
  const showStream = frame >= fallStart && frame <= fallEnd;

  // --- SVG Paths (Based on a 200x300 viewBox) ---
  const leftWall = "M 30 20 C 30 100 80 135 97 150 C 80 165 30 200 30 280";
  const rightWall = "M 170 20 C 170 100 120 135 103 150 C 120 165 170 200 170 280";
  
  const topClipPath = "M 30 20 C 30 100 80 135 97 150 L 103 150 C 120 135 170 100 170 20 Z";
  const bottomClipPath = "M 97 150 L 103 150 C 120 165 170 200 170 280 L 30 280 C 30 200 80 165 97 150 Z";

  // Top sand has a concave dip in the middle
  const topSandShape = "M -20 20 Q 100 70 220 20 L 220 200 L -20 200 Z";
  
  // Bottom sand has a convex mound in the middle
  const bottomSandShape = "M -20 50 Q 100 -20 220 50 L 220 300 L -20 300 Z";

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          width: svgWidth,
          height: svgHeight,
          transform: `scale(${entranceScale})`,
          opacity: entranceOpacity,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <svg
          viewBox="0 0 200 300"
          style={{ width: "100%", height: "100%", overflow: "visible" }}
        >
          <defs>
            <clipPath id="top-glass-clip">
              <path d={topClipPath} />
            </clipPath>
            <clipPath id="bottom-glass-clip">
              <path d={bottomClipPath} />
            </clipPath>
          </defs>

          {/* Sand Elements Group */}
          <g>
            {/* Top Sand */}
            <g clipPath="url(#top-glass-clip)">
              <path
                d={topSandShape}
                fill={sandColor}
                transform={`translate(0, ${topSandY})`}
              />
            </g>

            {/* Bottom Sand */}
            <g clipPath="url(#bottom-glass-clip)">
              <path
                d={bottomSandShape}
                fill={sandColor}
                transform={`translate(0, ${bottomSandY})`}
              />
            </g>

            {/* Falling Sand Stream */}
            {showStream && (
              <line
                x1="100"
                y1={streamTopY}
                x2="100"
                y2={streamBottomY}
                stroke={sandColor}
                strokeWidth="4"
                strokeLinecap="round"
              />
            )}
          </g>

          {/* Hourglass Glass Outlines */}
          <path
            d={leftWall}
            fill="none"
            stroke={hourglassColor}
            strokeWidth="6"
            strokeLinecap="round"
          />
          <path
            d={rightWall}
            fill="none"
            stroke={hourglassColor}
            strokeWidth="6"
            strokeLinecap="round"
          />

          {/* Caps (Overlapping the glass slightly) */}
          <rect
            x="20"
            y="10"
            width="160"
            height="12"
            rx="4"
            fill={hourglassColor}
          />
          <rect
            x="20"
            y="278"
            width="160"
            height="12"
            rx="4"
            fill={hourglassColor}
          />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default HourglassAnimation;